import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
const check = (input, expected) => assert.equal(slugify(input), expected, JSON.stringify(input));

if (mode === 'latin') {
  for (const [input, expected] of [
    ['Crème Brûlée', 'creme-brulee'], ['Łódź', 'lodz'],
    ['  Crème, Brûlée! 2.0 ', 'creme-brulee-2-0'],
    ['Ångström déjà vu São Tomé', 'angstrom-deja-vu-sao-tome'],
    ['Dvořák İSTANBUL Việt Nam', 'dvorak-istanbul-viet-nam'],
    ['Cafe\u0301 au lait', 'cafe-au-lait'],
    ['a\u0308\u0304 b\u0327\u0301 c\u1ab0 d\u1dc0 e\ufe20', 'a-b-c-d-e'],
    ['Ł\u0301 æ\u0304 ß\u0307', 'l-ae-ss'],
    ['Crème Ελληνικά Łódź 日本語 ø Привет', 'creme-ελληνικά-lodz-日本語-o-привет'],
  ]) check(input, expected);

  // Exercise every canonically accented Latin letter with an ASCII base,
  // both as a precomposed code point and in decomposed spelling.
  let covered = 0;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const ch = String.fromCodePoint(cp);
    if (!/\p{L}/u.test(ch) || !/\p{Script=Latin}/u.test(ch)) continue;
    const decomposed = ch.normalize('NFD');
    if (!/^[A-Za-z]\p{M}+$/u.test(decomposed)) continue;
    const expected = decomposed[0].toLowerCase();
    check(ch, expected);
    check(decomposed, expected);
    check('x' + ch + 'y', 'x' + expected + 'y');
    check('x' + decomposed + 'y', 'x' + expected + 'y');
    covered++;
  }
  assert.ok(covered > 400, 'Unicode accent corpus must be exercised');
} else if (mode === 'special') {
  // Non-decomposing letters and conventional Latin ligatures.
  const mappings = [
    ['ø', 'o'], ['ł', 'l'], ['đ', 'd'], ['ð', 'd'], ['þ', 'th'],
    ['æ', 'ae'], ['œ', 'oe'], ['ß', 'ss'], ['ẞ', 'ss'],
    ['ħ', 'h'], ['ı', 'i'], ['ſ', 's'], ['ŋ', 'n'], ['ŧ', 't'],
    ['ƒ', 'f'], ['ĳ', 'ij'],
    ['ǽ', 'ae'], ['ǣ', 'ae'], ['ǿ', 'o'],
    ['ﬀ', 'ff'], ['ﬁ', 'fi'], ['ﬂ', 'fl'], ['ﬃ', 'ffi'],
    ['ﬄ', 'ffl'], ['ﬅ', 'st'], ['ﬆ', 'st'],
  ];
  for (const [letter, ascii] of mappings) {
    for (const input of new Set([letter, letter.toUpperCase()])) {
      check(input, ascii);
      check('A' + input + 'Z', 'a' + ascii + 'z');
      check('! ' + input + '\u0301 ?', ascii);
    }
  }
  check('smørrebrød Straße Æsir Œuvre Þingvellir', 'smorrebrod-strasse-aesir-oeuvre-thingvellir');
} else if (mode === 'regression') {
  for (const [input, expected] of [
    ['', ''], ['  --___!!!  ', ''], ['Hello, World!', 'hello-world'],
    ['  --Release 2.0--  ', 'release-2-0'], ['a_b/c\\d', 'a-b-c-d'],
    ['a\n\tb   c', 'a-b-c'], ['a😀🚀b', 'a-b'], ['123 ٤٥६ １２３', '123-٤٥६-１２３'],
    ['Привет мир', 'привет-мир'], ['ЙЁ йё', 'йё-йё'],
    ['Ελληνικά ΆΈΉΊΌΎΏ ΐΰ', 'ελληνικά-άέήίόύώ-ΐΰ'],
    ['日本語 がぎぐげご ガギグゲゴ', '日本語-がぎぐげご-ガギグゲゴ'],
    ['한글 中文', '한글-中文'], ['Հայերեն ქართული', 'հայերեն-ქართული'],
    ['עברית العربية', 'עברית-العربية'],
  ]) check(input, expected);
  // All non-Latin letters retain the old lower-case/separator behavior.
  // In particular, canonical normalization must not rewrite other scripts.
  const old = s => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
  let covered = 0;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const ch = String.fromCodePoint(cp);
    if (!/\p{L}/u.test(ch) || /\p{Script=Latin}/u.test(ch)) continue;
    check(ch, old(ch));
    covered++;
  }
  assert.ok(covered > 100000);
} else {
  throw new Error('Unknown acceptance mode: ' + mode);
}
console.log('Acceptance checks passed: ' + mode);
